head.script:

// 사전에 groupby() 로 설정해 둘 표시 옵션 10종 (이벤트로 전달되어야 하는 대상)
scwin.PRE_OPTIONS = {
    sortIndex          : [0],
    sortOrder          : [1],
    hideHeader         : false,
    hideFooter         : false,
    groupbyHeader      : [
        { colSpan: 3, inputType: "expression", expression: " toggle() + depthStr() ", align: "left" },
        { colSpan: 1, inputType: "expression", expression: " sum('col4') ", displayFormatType: "number", displayFormat: "#,###", align: "right" }
    ],
    groupbyFooter      : [
        { colSpan: 3, inputType: "expression", expression: " '소계' ", align: "left" },
        { colSpan: 1, inputType: "expression", expression: " sum('col4') ", displayFormatType: "number", displayFormat: "#,###", align: "right" }
    ],
    closeGroup         : false,
    showOnlyLastDepth  : true,
    rowNumHeader       : { colSpan: 1, inputType: "expression", expression: " count() " },
    rowStatusHeader    : { colSpan: 1 },
    rowNumFooter       : { colSpan: 1, value: "계" },
    rowStatusFooter    : { colSpan: 1, className: "tc_groupby_footer_status" }
};

// 이벤트로 전달되어야 하는 표시 옵션 10종
scwin.TARGET_KEYS = ["hideHeader", "hideFooter", "groupbyHeader", "groupbyFooter", "closeGroup",
                     "showOnlyLastDepth", "rowNumHeader", "rowStatusHeader", "rowNumFooter", "rowStatusFooter"];

scwin.fmt = function (v) {
    if (typeof v === "undefined") { return "undefined"; }
    if (v === null) { return "null"; }
    if (typeof v === "object") { return JSON.stringify(v); }
    return String(v);
};

// 표시 옵션 10종 중 엔진에 보관된(undefined 가 아닌) 항목 수를 센다.
scwin.countKept = function (data) {
    var cnt = 0;
    for (var i = 0; i < scwin.TARGET_KEYS.length; i++) {
        if (data && typeof data[scwin.TARGET_KEYS[i]] !== "undefined") { cnt++; }
    }
    return cnt;
};

scwin.onpageload = function () {
    // 사전 조건 : 표시 옵션 10종을 모두 지정하여 GroupBy 를 미리 적용해 둔다.
    grd_defect.groupby(scwin.PRE_OPTIONS);
    scwin.setReturnValue("[사전설정] groupby() 로 표시 옵션 10종 지정 완료 (getGroupbyData 보관 "
        + scwin.countKept(grd_defect.getGroupbyData()) + "/" + scwin.TARGET_KEYS.length + " 종)");
    scwin.setReturnValue("");
};

// ongroupby : GroupBy Zone Drag&Drop / 컨텍스트 메뉴 '선택 컬럼 그룹' 시 발생
scwin.grd_defect_ongroupby = function (result) {
    // 이벤트 발생 시점의 엔진 보관값 (기대값)
    var stored = grd_defect.getGroupbyData();
    scwin.setReturnValue("[이벤트발생] ongroupby - 표시 옵션 10종 [기대(엔진 보관값 getGroupbyData) vs 실제(전달값 result)]");
    for (var i = 0; i < scwin.TARGET_KEYS.length; i++) {
        var key = scwin.TARGET_KEYS[i];
        scwin.setReturnValue("[" + key + "] 기대 : " + scwin.fmt(stored ? stored[key] : undefined)
            + " / 실제 : " + scwin.fmt(result[key]));
    }
    scwin.setReturnValue("");
    // 가이드 사용 패턴 : 전달받은 인자에 표시 옵션을 정의한 뒤 groupby() 를 수동 호출
    for (var j = 0; j < scwin.TARGET_KEYS.length; j++) {
        result[scwin.TARGET_KEYS[j]] = scwin.PRE_OPTIONS[scwin.TARGET_KEYS[j]];
    }
    grd_defect.groupby(result);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
